const allCases = [];
for (const item of $input.all()) {
  const body = item.json.body;
  if (Array.isArray(body)) {
    allCases.push(...body);
  } else if (body && Array.isArray(body.cases)) {
    allCases.push(...body.cases);
  }
}
console.log('Total cases de MyCase: ' + allCases.length);
return [{ json: { cases: allCases, total: allCases.length } }];

const mycaseCases = $('Extract All Cases').first().json.cases;

function normalize(str) {
  if (!str && str !== 0) return '';
  return str.toString()
    .toLowerCase()
    .replace(/[\s\-\/\.]/g, '')
    .replace(/[^a-z0-9]/g, '');
}

const caseNoMap = {};
const nameMap = {};

for (const c of mycaseCases) {
  if (c.case_number) {
    const key = normalize(c.case_number);
    if (key) caseNoMap[key] = c;
  }
  if (c.name) {
    const key = normalize(c.name);
    if (key) nameMap[key] = c;
  }
}

console.log('Lookup: ' + Object.keys(caseNoMap).length + ' por case_no, ' + Object.keys(nameMap).length + ' por nombre');

const results = [];
let countCaseNo = 0, countName = 0, countNoMatch = 0, countSkipped = 0;

for (const item of $input.all()) {
  const row = item.json;
  const clientName = (row['Client Name'] || '').toString().trim();
  const caseNo = (row['Case No.'] || '').toString().trim();

  if (!clientName || clientName.toUpperCase() === 'TOTAL') {
    countSkipped++;
    continue;
  }

  let matchedCase = null;
  let matchMethod = 'NO MATCH';

  const normCaseNo = normalize(caseNo);
  if (normCaseNo && caseNoMap[normCaseNo]) {
    matchedCase = caseNoMap[normCaseNo];
    matchMethod = 'CASE_NO';
    countCaseNo++;
  }

  if (!matchedCase) {
    const normName = normalize(clientName);
    if (normName && nameMap[normName]) {
      matchedCase = nameMap[normName];
      matchMethod = 'NAME_EXACT';
      countName++;
    }
  }

  if (!matchedCase) {
    const normName = normalize(clientName);
    if (normName.length >= 5) {
      for (const [key, c] of Object.entries(nameMap)) {
        if (key.includes(normName) || normName.includes(key)) {
          matchedCase = c;
          matchMethod = 'NAME_PARTIAL';
          countName++;
          break;
        }
      }
    }
  }

  if (!matchedCase) countNoMatch++;

  results.push({
    json: {
      'Client (Sheet)': clientName,
      'Case No. (Sheet)': caseNo,
      'MyCase ID': matchedCase ? String(matchedCase.id) : '',
      'MyCase Case No.': matchedCase ? String(matchedCase.case_number) : '',
      'MyCase Name': matchedCase ? String(matchedCase.name) : '',
      'Status': matchedCase ? String(matchedCase.status || '') : '',
      'Match Method': matchMethod
    }
  });
}

console.log('Resumen: CASE_NO=' + countCaseNo + ', NAME=' + countName + ', NO_MATCH=' + countNoMatch + ', SKIPPED=' + countSkipped);
return results;
